package br.com.sistemacardapio.complemento;
import java.math.BigDecimal;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import br.com.sistemacardapio.catalogo.ProdutoRepository;import br.com.sistemacardapio.empresa.*;import br.com.sistemacardapio.tenant.TenantContext;
@Service public class GrupoComplementoService{private final GrupoComplementoRepository grupos;private final ComplementoRepository itens;private final EmpresaRepository empresas;private final ProdutoRepository produtos;private final TenantContext tenant;private final JdbcTemplate jdbc;
 public GrupoComplementoService(GrupoComplementoRepository g,ComplementoRepository i,EmpresaRepository e,ProdutoRepository p,TenantContext t,JdbcTemplate j){grupos=g;itens=i;empresas=e;produtos=p;tenant=t;jdbc=j;}
 @Transactional(readOnly=true)public List<Response>listar(){UUID e=tenant.empresaIdObrigatoria();return grupos.findAllByEmpresaIdOrderByNomeAsc(e).stream().map(g->response(g,e)).toList();}
 @Transactional public Response criar(Request r){UUID e=tenant.empresaIdObrigatoria();validar(r,e);GrupoComplemento g=grupos.save(new GrupoComplemento(empresas.findById(e).orElseThrow(),r.nome(),r.obrigatorio(),r.minimo(),r.maximo()));salvarItens(g,r.itens(),e);vincular(g,r.produtoIds(),e);return response(g,e);}
 @Transactional public Response atualizar(UUID id,Request r){UUID e=tenant.empresaIdObrigatoria();validar(r,e);GrupoComplemento g=grupos.findByIdAndEmpresaId(id,e).orElseThrow(()->new IllegalStateException("Grupo não encontrado"));g.atualizar(r.nome(),r.obrigatorio(),r.minimo(),r.maximo(),r.ativo());salvarItens(g,r.itens(),e);vincular(g,r.produtoIds(),e);return response(g,e);}
 private void validar(Request r,UUID e){if(r.minimo()<0||r.maximo()<1||r.minimo()>r.maximo())throw new IllegalStateException("Limites do grupo são inválidos");for(UUID p:r.produtoIds())if(produtos.findByIdAndEmpresaId(p,e).isEmpty())throw new IllegalStateException("Produto não encontrado");}
 private void salvarItens(GrupoComplemento g,List<ItemRequest> requests,UUID e){Set<UUID>presentes=new HashSet<>();for(ItemRequest r:requests){Complemento item=r.id()==null?new Complemento(g,r.nome(),r.preco(),r.ordem()):itens.findByIdAndGrupoIdAndEmpresaId(r.id(),g.getId(),e).orElseThrow(()->new IllegalStateException("Complemento não encontrado"));item.atualizar(r.nome(),r.preco(),r.ordem(),r.ativo());itens.save(item);presentes.add(item.getId());}for(Complemento atual:itens.findAllByGrupoIdOrderByOrdemAscNomeAsc(g.getId()))if(!presentes.contains(atual.getId()))atual.atualizar(atual.getNome(),atual.getPreco(),atual.getOrdem(),false);}
 private void vincular(GrupoComplemento g,List<UUID> p,UUID e){jdbc.update("delete from produto_grupo_complemento where empresa_id=? and grupo_id=?",e,g.getId());int ordem=0;for(UUID id:p)jdbc.update("insert into produto_grupo_complemento(empresa_id,produto_id,grupo_id,ordem) values(?,?,?,?)",e,id,g.getId(),ordem++);}
 private Response response(GrupoComplemento g,UUID e){List<ItemResponse>is=itens.findAllByGrupoIdOrderByOrdemAscNomeAsc(g.getId()).stream().map(ItemResponse::from).toList();List<UUID>ps=jdbc.query("select produto_id from produto_grupo_complemento where empresa_id=? and grupo_id=? order by ordem",(rs,n)->rs.getObject(1,UUID.class),e,g.getId());return new Response(g.getId(),g.getNome(),g.isObrigatorio(),g.getMinimo(),g.getMaximo(),g.isAtivo(),is,ps);}
 public record Request(@jakarta.validation.constraints.NotBlank String nome,boolean obrigatorio,int minimo,int maximo,boolean ativo,@jakarta.validation.Valid List<ItemRequest> itens,List<UUID> produtoIds){public Request{itens=itens==null?List.of():itens;produtoIds=produtoIds==null?List.of():produtoIds;}}public record ItemRequest(UUID id,@jakarta.validation.constraints.NotBlank String nome,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.PositiveOrZero BigDecimal preco,int ordem,boolean ativo){}public record ItemResponse(UUID id,String nome,BigDecimal preco,int ordem,boolean ativo){static ItemResponse from(Complemento i){return new ItemResponse(i.getId(),i.getNome(),i.getPreco(),i.getOrdem(),i.isAtivo());}}public record Response(UUID id,String nome,boolean obrigatorio,int minimo,int maximo,boolean ativo,List<ItemResponse>itens,List<UUID>produtoIds){}
}
